      "{\"@context\":\"https://schema.org\",\"@type\":\"BlogPosting\",\"headline\":\"Tema pe care ai ales-o e cea mai scumpă decizie tehnică din magazin\",\"description\":\"De ce structura temei decide viteza, lizibilitatea pentru roboți și costul oricărei schimbări ulterioare într-un magazin online.\",\"image\":\"https://vidgotech.com/assets/blog-structura-temei-magazin.png\",\"datePublished\":\"2026-08-24\",\"dateModified\":\"2026-08-24\",\"inLanguage\":\"ro-RO\",\"mainEntityOfPage\":\"https://vidgotech.com/blog/structura-temei-magazin\",\"author\":{\"@type\":\"Person\",\"name\":\"Ioana Dinu\",\"url\":\"https://vidgotech.com/despre\"},\"publisher\":{\"@type\":\"Organization\",\"name\":\"VidGo Technologies\",\"url\":\"https://vidgotech.com/\"},\"keywords\":[\"tema magazin\",\"skin\",\"WooCommerce\",\"PrestaShop\",\"performanta\",\"pluginuri\",\"design storefront\"]}",
