      "{\"@context\":\"https://schema.org\",\"@type\":\"BlogPosting\",\"headline\":\"Cum devine un magazin online vizibil în Google și în răspunsurile AI\",\"description\":\"Ghid despre robots.txt, sitemap, llms.txt, Merchant Center, date structurate și instrumente AI pentru ecommerce.\",\"image\":\"https://vidgotech.com/assets/blog-vizibilitate-google-ai.png\",\"datePublished\":\"2026-08-12\",\"dateModified\":\"2026-10-30\",\"inLanguage\":\"ro-RO\",\"mainEntityOfPage\":\"https://vidgotech.com/blog/vizibilitate-google-ai\",\"author\":{\"@type\":\"Person\",\"name\":\"Ioana Dinu\",\"url\":\"https://vidgotech.com/despre\"},\"publisher\":{\"@type\":\"Organization\",\"name\":\"VidGo Technologies\",\"url\":\"https://vidgotech.com/\"},\"keywords\":[\"optimizare SEO magazin online\",\"SEO ecommerce\",\"AI search\",\"Google Merchant Center\",\"robots.txt\",\"sitemap\",\"llms.txt\",\"căutare AI\"]}",
